import{_ as e,c as p,o as r,af as i}from"./chunks/framework.BKeRpnBD.js";const _=JSON.parse('{"title":"22、【贲】 离下艮上","description":"周易集注 - 22、【贲】 离下艮上","frontmatter":{"title":"22、【贲】 离下艮上","description":"周易集注 - 22、【贲】 离下艮上"},"headers":[],"relativePath":"zh/classics/jizhu/026.md","filePath":"zh/classics/jizhu/026.md"}'),h={name:"zh/classics/jizhu/026.md"};function t(l,a,s,n,c,d){return r(),p("div",null,[...a[0]||(a[0]=[i('<h1 id="_22、【贲】-离下艮上" tabindex="-1">22、【贲】 离下艮上 <a class="header-anchor" href="#_22、【贲】-离下艮上" aria-label="Permalink to “22、【贲】 离下艮上”">​</a></h1><p>贲饰也，为卦山下有火，山者百物草木之所聚，下有火，则照见其上，品汇皆被光彩，贲之象也。《序卦》：“嗑者合也，物不可以苟合也，故受之以贲。”所以次噬嗑。</p><p>小利攸往，亦为亨，但亨之不大耳。</p><p>《彖》曰：贲亨，柔来而文刚，故亨。分刚上而文柔，故小利有攸往，天文也;文明以止，人文也。观乎天文，以察时变;观乎人文，以化成天下。</p><p>以卦综、卦德释卦辞，而极言之。本卦综噬嗑，柔来文刚者，噬嗑上卦之柔，来文贲之刚也，柔指离之阴卦，刚则艮之阳卦也。柔来文刚，以成离明，内而离明，则足以照物，动罔不臧，所以亨。分者，又分下卦也。分刚上而文柔者，分噬嗑下卦之刚，上而为艮，以文柔也，刚指震之阳卦，柔则离之阴卦也。刚上而文柔，以成艮止，外而艮止，则内而能知之，外而不能行之，仅可小利有攸往而已，不能建大功业也，故以其卦综观之，柔来文刚，刚上文柔，是即天之文也，何也?盖在天成象，日月五星之运行，不过此一刚一柔，一往一来而已，今本卦刚柔交错，是贲之文，即天之文也，以其卦德观之，是即人之文也，何也?盖人之所谓文者，不过文之明也，而灿然有礼以相接，文之止也，而截然有分以相守，今本卦内而离明，外而艮止，是贲之文，即人之文也，观天文以察时变，观人文以化成天下，贲之文不其大哉!变者，四时寒暑代谢之变也，化者，变而为新，成者，久而成俗。</p><h3 id="《象》曰-山下有火-贲-君子以明庶政-无敢折狱。" tabindex="-1">《象》曰：山下有火，贲，君子以明庶政，无敢折狱。 <a class="header-anchor" href="#《象》曰-山下有火-贲-君子以明庶政-无敢折狱。" aria-label="Permalink to “《象》曰：山下有火，贲，君子以明庶政，无敢折狱。”">​</a></h3><p>明，离象。无敢，艮象。庶者，众也。繁庶小事，如钱谷出纳之类，折狱则一轻重出入之间，民命之死生所系，乃大事也，曰“无敢”者，非不折狱也，不敢轻折狱也，再三详审，而后发之意，此即小利有攸往之理。因内明外止，其取象如此，贲与噬嗑相综，噬嗑利用狱者，明因雷而动也，贲不敢折狱者，明因艮而止也。</p><p>初九，贲其趾，舍车而徒。(舍音舍)</p><p>贲其趾者，道义以文饰其足趾也，舍者弃也，徒者徒行也，舍车而徒，即贲其趾也，言舍车之荣而徒行，是不以徒行为辱，而自以道义为荣也。中爻震与坎，震，趾之象也;坎，车之象也，变艮，止而又止，舍之象也。初比二而应四，比二则从乎坎车矣，应四则从乎震趾矣，然升乎车者，必在上，方可乘，易中言乘者，皆在上也，言承者，皆在下也，初在下，无乘之理，故有舍坎车而从震趾之象，观小象乘字可见。</p><p>初九刚德明体，盖内重外轻，自贲于下而隐者也，故有舍非义之车，而安于徒步之象，占者得此，当以此自处也。</p><h3 id="《象》曰-舍车而徒-义弗乘也。" tabindex="-1">《象》曰：舍车而徒，义弗乘也。 <a class="header-anchor" href="#《象》曰-舍车而徒-义弗乘也。" aria-label="Permalink to “《象》曰：舍车而徒，义弗乘也。”">​</a></h3><p>初在下，无可乘之理。</p><p>六二，贲其须。</p><p>在颐曰须，在口曰髭，在颊曰髯，须不能以自动，随颐而动，则须虽美，乃附于颐以为文者也。本卦综噬嗑，原有颐象，今变阳则中爻为兑口矣，口旁之文，莫如须，故以须象之。</p><p>六二以阴柔居中正，三以阳刚得正，皆无应与，故二附三而动，犹须附颐而动也，故有贲其须之象，占者附其君子，斯无愧于贲矣。</p><h3 id="《象》曰-贲其须-与上兴也。" tabindex="-1">《象》曰：贲其须，与上兴也。 <a class="header-anchor" href="#《象》曰-贲其须-与上兴也。" aria-label="Permalink to “《象》曰：贲其须，与上兴也。”">​</a></h3><p>与者相从也，兴者兴起也。二阴柔从三阳兴起者也。</p><p>九三，贲如濡如，永贞吉。</p><p>如，助语辞。濡，沾濡也。离文自饰，贲如之象也，中爻坎水自润，濡水之象也。永贞者，长永其贞也，九三本贞，教之以永其贞也，吉者阴终不能陵也。</p><p>九三以一阳居二阴之间，当贲之时，阴本比己，为之左右先后，盖得其贲而润泽者也，故有贲如濡如之象，然不可溺于所安也。占者能守永贞之戒，斯吉矣。</p><h3 id="《象》曰-永贞之吉-终莫之陵也。" tabindex="-1">《象》曰：永贞之吉，终莫之陵也。 <a class="header-anchor" href="#《象》曰-永贞之吉-终莫之陵也。" aria-label="Permalink to “《象》曰：永贞之吉，终莫之陵也。”">​</a></h3><p>陵者侮也，能永其贞，则不陷溺于阴柔之中，有所严惮，终莫之陵侮矣。</p><p>六四，贲如皤如，白马翰如，匪寇婚媾。(皤白波反)</p><p>皤，白也，四变中爻为巽，白之象也。贲如皤如者，言未成其贲而成其皤也，非贲如而又皤如也。中爻震为馵足，为的颡，馵白足，颡白颠，白马之象也，旧注不知象，故言人白，则马亦白，无是理矣。翰如者，马如翰之飞也，中爻坎，坎为亟心之马，翰如之象也，寇指三，婚媾指初。</p><p>六四与初为正应，盖相为贲者也，乃为九三所隔，而不得遂，故未成其贲，而成其皤，然四往求于初之心，如飞翰之疾，不以三之隔而遂己也，使非三之寇，则与初成婚媾，而相为贲矣，是以始虽相隔，而终则相亲也，即象而占可知矣，与屯六二同。</p><h3 id="《象》曰-六四-当位-疑也。匪寇婚媾-终无尤也。" tabindex="-1">《象》曰：六四，当位，疑也。匪寇婚媾，终无尤也。 <a class="header-anchor" href="#《象》曰-六四-当位-疑也。匪寇婚媾-终无尤也。" aria-label="Permalink to “《象》曰：六四，当位，疑也。匪寇婚媾，终无尤也。”">​</a></h3><p>以阴居阴，故当位，疑者，疑惧其三之亲比也，六四守正，三不能求，故终无过尤。</p><p>六五，贲于丘园，束帛戋戋，吝，终吉。(戋音残)</p><p>艮为山，丘之象也，故颐卦指上九为丘，涣卦中爻艮，故六四涣其丘。艮为果蓏，又居中爻震木之上，果蓏林木，园之象也，此丘园指上九，上九贲白，贫贱肆志，乃山林高蹈之贤，蛊乃同体之卦，上九不事王侯，随卦上六错艮，亦曰西山，则上九乃山林之贤无疑矣。两疋为束，阴爻两坼，束之象也。坤为帛，此坤土帛之象也。戋与残同，伤也，艮错兑，为毁折，戋之象也。束帛伤戋，即今人之礼缎也。本卦上体下体皆外阳中虚，有礼缎之象，上戋下戋，故曰戋戋，阴吝啬，故曰吝。</p><p>六五文明以止之主，当贲之时，下无应与，乃上比上九高蹈之贤，故有光贲丘园，束帛以聘之象。然贲道将终，文反于质，故又有戋戋之象，以此为礼，有似于吝，然礼薄意勤，礼贤下士，乃人君可喜之事，占者得此，吉可知矣。</p><h3 id="《象》曰-六五之吉-有喜也。" tabindex="-1">《象》曰：六五之吉，有喜也。 <a class="header-anchor" href="#《象》曰-六五之吉-有喜也。" aria-label="Permalink to “《象》曰：六五之吉，有喜也。”">​</a></h3><p>艮错兑为悦，故曰有喜，得上九高贤而文之，岂不喜。</p><p>上九，白贲，无咎。</p><p>贲文也，白质也，故曰白受采，上九居贲之极，物极则反，有色复于无色，所以有白贲之象，文胜而反于质，无咎之道也，故其象占如此。</p><h3 id="《象》曰-白贲无咎-上得志也。" tabindex="-1">《象》曰：白贲无咎，上得志也。 <a class="header-anchor" href="#《象》曰-白贲无咎-上得志也。" aria-label="Permalink to “《象》曰：白贲无咎，上得志也。”">​</a></h3><p>文胜而反于质，退居山林之地，六五之君，以束帛聘之，岂不得志。此以人事言者也，若以卦综论之，此文原是噬嗑初爻，刚上文柔，以下居上，所以得志。</p>',36)])])}const f=e(h,[["render",t]]);export{_ as __pageData,f as default};
